package main

import (
	"database/sql"
	"log"
	"net/http"
	"os"

	"linkshelf/internal/api"
	"linkshelf/internal/store"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	// Determine database path (use environment variable or default)
	dbPath := os.Getenv("LINKDB_PATH")
	if dbPath == "" {
		dbPath = "linkshelf.db"
	}

	db, err := sql.Open("sqlite3", dbPath)
	if err != nil {
		log.Fatalf("Failed to open database: %v", err)
	}
	defer db.Close()

	// Initialize schema
	if err := api.InitSchema(db); err != nil {
		log.Fatalf("Failed to initialize schema: %v", err)
	}

	// Assign the DB to the store package-level variable
	store.DB = db

	// Register routes using the default mux
	mux := http.NewServeMux()

	// Static files
	mux.HandleFunc("/static/", api.ServeStatic)
	mux.HandleFunc("/", api.ServeIndex)

	// API routes
	mux.HandleFunc("/api/links", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.ListLinks(w, r)
		case http.MethodPost:
			api.CreateLink(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	mux.HandleFunc("/api/links/", func(w http.ResponseWriter, r *http.Request) {
		// Only DELETE is supported for sub-path
		if r.Method != http.MethodDelete {
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			return
		}
		api.DeleteLink(w, r)
	})

	addr := os.Getenv("LISTEN_ADDR")
	if addr == "" {
		addr = ":8080"
	}

	log.Printf("Starting server on %s", addr)
	if err := http.ListenAndServe(addr, mux); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}

